const items = $input.all();

return [{
  json: {
    children: items.map(i => String(i.json.id)).join(','),
    caption: items[0].json.caption,
    proposal_id: items[0].json.proposal_id,
  },
}];

const urls = typeof $json.image_urls === 'string'
  ? JSON.parse($json.image_urls)
  : $json.image_urls;

if (!Array.isArray(urls) || urls.length < 2 || urls.length > 10) {
  throw new Error('Un carrusel de Instagram debe tener entre 2 y 10 fotos.');
}

return urls.map((image_url) => ({
  json: {
    image_url,
    caption: $json.caption,
    proposal_id: $json.id,
  },
}));
